using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Provides a web search tool that the agent can call to find information on the internet.
/// Replace the simulated results with a real search API (Bing, Google, Brave) for production use.
/// </summary>
public sealed class WebSearchTool
{
    private readonly HttpClient _httpClient;

    public WebSearchTool(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [Description("Search the web for information on a given query. Returns a list of search results with titles, snippets, and URLs.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query to look up on the web")] string query,
        [Description("Maximum number of results to return (default 5)")] int maxResults = 5)
    {
        // In production, replace this with a real search API call, e.g.:
        //   GET https://api.bing.microsoft.com/v7.0/search?q={query}
        //   with Ocp-Apim-Subscription-Key header
        var results = await SimulateSearchAsync(query, maxResults);
        return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
    }

    private Task<List<SearchResult>> SimulateSearchAsync(string query, int maxResults)
    {
        // Simulated search results for demonstration purposes.
        var results = new List<SearchResult>
        {
            new("Understanding " + query,
                $"A comprehensive overview of {query}, covering key concepts, recent developments, and practical applications in the field.",
                $"https://example.com/articles/{Uri.EscapeDataString(query.ToLowerInvariant())}-overview"),

            new("Recent Advances in " + query,
                $"Researchers have made significant breakthroughs in {query}. New techniques improve efficiency by up to 40% compared to previous approaches.",
                $"https://example.com/research/{Uri.EscapeDataString(query.ToLowerInvariant())}-advances"),

            new(query + " - Best Practices Guide",
                $"Industry experts recommend these best practices for {query}: start with fundamentals, iterate quickly, measure outcomes, and stay current with evolving standards.",
                $"https://example.com/guides/{Uri.EscapeDataString(query.ToLowerInvariant())}-best-practices"),

            new("The Future of " + query,
                $"Analysts predict that {query} will transform multiple industries over the next decade, driven by increased adoption, improved tooling, and growing community support.",
                $"https://example.com/predictions/{Uri.EscapeDataString(query.ToLowerInvariant())}-future"),

            new(query + " Case Studies",
                $"Real-world case studies demonstrate how organizations have successfully implemented {query} to solve complex problems and achieve measurable business impact.",
                $"https://example.com/cases/{Uri.EscapeDataString(query.ToLowerInvariant())}-case-studies"),
        };

        return Task.FromResult(results.Take(maxResults).ToList());
    }

    private record SearchResult(string Title, string Snippet, string Url);
}

using System.ComponentModel;
using System.Text.Json;

namespace ResearchAgent;

/// <summary>
/// Provides note-taking capabilities so the agent can record key findings during research.
/// </summary>
public sealed class NoteTool
{
    private readonly List<Note> _notes = [];

    [Description("Save a research note with a title and content. Use this to record key findings during research.")]
    public string SaveNote(
        [Description("A short title for the note")] string title,
        [Description("The content of the note with key findings")] string content)
    {
        var note = new Note(title, content, DateTime.UtcNow);
        _notes.Add(note);
        return $"Note saved: \"{title}\" ({_notes.Count} total notes)";
    }

    [Description("Retrieve all saved research notes to review findings before writing a summary.")]
    public string GetAllNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        return JsonSerializer.Serialize(_notes, new JsonSerializerOptions { WriteIndented = true });
    }

    [Description("Get the total number of notes saved so far.")]
    public string GetNoteCount()
    {
        return $"{_notes.Count} note(s) saved.";
    }

    private record Note(string Title, string Content, DateTime SavedAt);
}

