using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using ResearchAgent;

var builder = Host.CreateApplicationBuilder(args);

// Resolve API key from environment or configuration — never hardcode.
var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable or AI:ApiKey in configuration.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

// Register tools as singletons so the agent can access them.
builder.Services.AddSingleton<WebSearchTool>();
builder.Services.AddSingleton<NoteTool>();
builder.Services.AddHttpClient<WebSearchTool>();

// Register the IChatClient via MEAI with function-calling middleware.
builder.Services.AddChatClient(chatBuilder => chatBuilder
    .UseFunctionInvocation()
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

var host = builder.Build();

// Resolve services.
var chatClient = host.Services.GetRequiredService<IChatClient>();
var webSearch = host.Services.GetRequiredService<WebSearchTool>();
var noteTool = host.Services.GetRequiredService<NoteTool>();

// Build tools from the tool instances.
var tools = new AITool[]
{
    AIFunctionFactory.Create(webSearch.SearchWebAsync),
    AIFunctionFactory.Create(noteTool.SaveNote),
    AIFunctionFactory.Create(noteTool.GetAllNotes),
    AIFunctionFactory.Create(noteTool.GetNoteCount),
};

// Create the agent with the Agent Framework.
var agent = new ChatClientAgent(
    chatClient,
    "ResearchAgent",
    """
    You are a research agent. Your job is to research a topic thoroughly and produce a summary.

    Follow this workflow:
    1. Search the web for information on the given topic using multiple queries.
    2. Save important findings as notes using the note-taking tool.
    3. Review all your notes.
    4. Produce a well-structured summary with key findings, citing sources where possible.

    Be thorough but concise. Focus on the most important and recent information.
    """,
    tools);

// Get the research topic from the user.
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent               ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.Write("\nEnter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}");
Console.WriteLine(new string('─', 50));

// Run the agent with guardrails.
var agentOptions = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

var chatOptions = new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
};

var messages = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

await foreach (var response in agent.InvokeStreamingAsync(messages, agentOptions, chatOptions))
{
    Console.Write(response.Text);
}

Console.WriteLine();
Console.WriteLine(new string('─', 50));
Console.WriteLine("Research complete.");

